  const bankInfo=order?.paymentMethod==="bank_transfer"?`<div class="alert info" style="text-align:left;margin:16px auto;max-width:560px"><i class="fa-solid fa-building-columns"></i><div><strong>Complete your bank transfer</strong><br>${escapeHtml(settings.bankName||"Configured bank")}<br>${settings.bankAccountName?`Account name: ${escapeHtml(settings.bankAccountName)}<br>`:""}${settings.bankAccountNumber?`Account number: ${escapeHtml(settings.bankAccountNumber)}<br>`:""}Use order reference <strong>${escapeHtml(id||"")}</strong>.</div></div>`:"";
