function showOrderModal(order){showModal(`<h2 id="modalTitle">Order ${escapeHtml(order.id)}</h2><div class="summary-line"><span>Status</span>${statusBadge(order.status)}</div><div class="summary-line"><span>Placed</span><span>${formatDate(order.createdAt)}</span></div><div class="summary-line"><span>Address</span><span>${escapeHtml(order.shippingAddress)}</span></div><hr style="border:0;border-top:1px solid var(--border)">${(order.items||[]).map(i=>`<div class="summary-line"><span>${escapeHtml(i.name)} × ${i.quantity}</span><strong>${formatMoney(i.subtotal)}</strong></div>`).join("")}<div class="summary-line summary-total"><span>Total</span><span>${formatMoney(order.total)}</span></div><button class="btn btn-primary btn-block" id="modalInvoice">Generate Invoice</button>`);qs("#modalInvoice").onclick=()=>printInvoice(order);}
function printInvoice(order){const win=window.open("","_blank");win.document.write(`<!doctype html><html><head><title>Invoice ${escapeHtml(order.id)}</title><style>body{font-family:Arial;padding:40px;color:#111}header{display:flex;justify-content:space-between;border-bottom:2px solid #1769ff;padding-bottom:20px}.brand{font-size:28px;font-weight:bold;color:#1769ff}table{width:100%;border-collapse:collapse;margin-top:25px}th,td{padding:10px;border-bottom:1px solid #ddd;text-align:left}.total{font-size:20px;font-weight:bold;text-align:right;margin-top:20px}.stamp{margin-top:40px;border:3px double #1769ff;color:#1769ff;border-radius:50%;width:110px;height:110px;display:grid;place-items:center;text-align:center;transform:rotate(-10deg);font-weight:bold}@media print{button{display:none}}</style></head><body><header><div><div class="brand">DhiExpress</div><div>Marketplace Invoice</div></div><div><strong>Invoice:</strong> ${escapeHtml(order.id)}<br><strong>Date:</strong> ${formatDate(order.createdAt)}</div></header><h3>Customer</h3><p>${escapeHtml(order.buyerName)}<br>${escapeHtml(order.buyerEmail)}<br>${escapeHtml(order.shippingAddress)}</p><table><thead><tr><th>Product</th><th>Qty</th><th>Price</th><th>Subtotal</th></tr></thead><tbody>${(order.items||[]).map(i=>`<tr><td>${escapeHtml(i.name)}</td><td>${i.quantity}</td><td>${formatMoney(i.price)}</td><td>${formatMoney(i.subtotal)}</td></tr>`).join("")}</tbody></table><div class="total">Total: ${formatMoney(order.total)}</div><p>Payment method: ${escapeHtml((order.paymentMethod||'').replaceAll('_',' '))}</p><div class="stamp">PAID /<br>ORDERED<br>DF7</div><p>Thank you for your business.</p><button onclick="print()">Print Invoice</button></body></html>`);win.document.close();}

