async function renderSellerDashboard() {
  if(!requireAuth())return;if(state.profile?.sellerStatus!=="approved"&&state.profile?.role!=="admin"){root().innerHTML=pageWrap(`${pageHeader("Seller Dashboard","Your seller tools and application status.")}<div class="dashboard-layout">${dashboardNav("seller-dashboard")}<section>${emptyState("fa-store","Seller approval required",state.profile?.sellerStatus==="pending"?"Your seller application is being reviewed.":"Create a seller profile before using seller tools.",'<a class="btn btn-primary" href="profile.html">Open Profile</a>')}</section></div>`);return;}const [products,orders]=await Promise.all([getMyProducts(),getOrders("seller")]);const revenue=orders.filter(o=>o.status==="delivered").reduce((s,o)=>s+(o.items||[]).filter(i=>i.sellerId===state.user.id).reduce((a,i)=>a+i.subtotal,0),0);root().innerHTML=pageWrap(`${pageHeader("Seller Dashboard","Manage products, customer orders, earnings and sales reports.",'<a class="btn btn-primary" href="add-product.html"><i class="fa-solid fa-plus"></i> Add Product</a>')}<div class="dashboard-layout">${dashboardNav("seller-dashboard")}<section class="dashboard-main"><div class="kpi-grid"><div class="kpi-card card"><div><span>Products</span><strong>${products.length}</strong></div><span class="kpi-icon"><i class="fa-solid fa-box"></i></span></div><div class="kpi-card card"><div><span>Orders received</span><strong>${orders.length}</strong></div><span class="kpi-icon"><i class="fa-solid fa-cart-flatbed"></i></span></div><div class="kpi-card card"><div><span>Delivered revenue</span><strong>${formatMoney(revenue)}</strong></div><span class="kpi-icon"><i class="fa-solid fa-coins"></i></span></div><div class="kpi-card card"><div><span>Current plan</span><strong>${escapeHtml(state.profile.planId||'None')}</strong></div><span class="kpi-icon"><i class="fa-solid fa-crown"></i></span></div></div><div class="card card-pad"><div class="section-title"><div><h2>Your listings</h2><p>Pending products require admin approval.</p></div></div>${products.length?`<div class="table-wrap"><table><thead><tr><th>Product</th><th>Price</th><th>Stock</th><th>Status</th><th>Created</th><th>Actions</th></tr></thead><tbody>${products.map(p=>`<tr><td><div class="table-product"><img src="${escapeHtml(p.images?.[0])}" alt=""><strong>${escapeHtml(p.name)}</strong></div></td><td>${formatMoney(p.discountPrice||p.price)}</td><td>${p.stock}</td><td>${statusBadge(p.status)}</td><td>${formatDate(p.createdAt)}</td><td class="table-actions"><a class="icon-action" href="edit-product.html?id=${p.id}"><i class="fa-solid fa-pen"></i></a><button class="icon-action" data-delete-product="${p.id}"><i class="fa-solid fa-trash"></i></button></td></tr>`).join("")}</tbody></table></div>`:emptyState("fa-box-open","No products yet","Create your first listing to start selling.",'<a class="btn btn-primary" href="add-product.html">Add Product</a>')}</div><div class="card card-pad" style="margin-top:20px"><div class="section-title"><div><h2>Customer orders</h2></div></div>${orders.length?`<div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Update</th></tr></thead><tbody>${orders.map(o=>`<tr><td>${escapeHtml(o.id)}</td><td>${escapeHtml(o.buyerName)}</td><td>${formatMoney((o.items||[]).filter(i=>i.sellerId===state.user.id).reduce((s,i)=>s+i.subtotal,0))}</td><td>${statusBadge(o.status)}</td><td><select data-order-status="${o.id}">${["pending","confirmed","processing","shipped","delivered","cancelled","refunded"].map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join("")}</select></td></tr>`).join("")}</tbody></table></div>`:emptyState("fa-truck","No seller orders","Orders containing your products will appear here.")}</div></section></div>`);
  qsa("[data-delete-product]").forEach(b=>b.onclick=async()=>{if(confirm("Delete this product?")){await deleteProductRecord(b.dataset.deleteProduct);toast("Product deleted.","success");renderSellerDashboard();}});qsa("[data-order-status]").forEach(s=>s.onchange=async()=>{await updateOrderStatus(s.dataset.orderStatus,s.value);toast("Order status updated.","success");});
}
async function renderProductForm(editing) {
  if(!requireAuth())return;const categories=await getCategories();let product=null;if(editing){product=await getProduct(getParam("id"));if(!product){root().innerHTML=pageWrap(emptyState("fa-box-open","Product not found","The product cannot be edited."));return;}}
  root().innerHTML=pageWrap(`${pageHeader(editing?"Edit Product":"Add Product",editing?"Update listing information, stock and images.":"Create a product listing for admin approval.")}<div class="dashboard-layout">${dashboardNav("seller-dashboard")}<section class="dashboard-main"><form id="productForm" class="card card-pad form-grid"><div class="form-grid cols-2"><div class="form-group" style="grid-column:1/-1"><label>Product name</label><input id="productName" required maxlength="120" value="${escapeHtml(product?.name||'')}"></div><div class="form-group" style="grid-column:1/-1"><label>Description</label><textarea id="productDescription" required minlength="20">${escapeHtml(product?.description||'')}</textarea></div><div class="form-group"><label>Category</label><select id="productCategory" required><option value="">Select category</option>${categories.map(c=>`<option value="${c.id}" ${c.id===product?.categoryId?'selected':''}>${escapeHtml(c.name)}</option>`).join("")}</select></div><div class="form-group"><label>Condition</label><select id="productCondition" required>${["New","Used","Refurbished"].map(x=>`<option ${x===product?.condition?'selected':''}>${x}</option>`).join("")}</select></div><div class="form-group"><label>Regular price (MVR)</label><input id="productPrice" type="number" min="0.01" step="0.01" required value="${product?.price||''}"></div><div class="form-group"><label>Discount price (optional)</label><input id="productDiscount" type="number" min="0" step="0.01" value="${product?.discountPrice||''}"></div><div class="form-group"><label>Stock quantity</label><input id="productStock" type="number" min="0" required value="${product?.stock??1}"></div><div class="form-group"><label>Location</label><input id="productLocation" required value="${escapeHtml(product?.location||state.profile?.location||'')}"></div><div class="form-group" style="grid-column:1/-1"><label>Delivery information</label><textarea id="productDelivery" required>${escapeHtml(product?.delivery||'')}</textarea></div><div class="form-group" style="grid-column:1/-1"><label>Product images (up to 8, maximum 5 MB each)</label><input id="productImages" type="file" accept="image/jpeg,image/png,image/webp" multiple><span class="form-help">Images are validated before upload. Existing images are kept when editing.</span>${product?.images?.length?`<div style="display:flex;gap:8px;flex-wrap:wrap">${product.images.map(i=>`<img src="${escapeHtml(i)}" alt="" style="width:80px;height:70px;object-fit:cover;border-radius:10px">`).join("")}</div>`:''}</div></div><button class="btn btn-primary" type="submit"><i class="fa-solid fa-cloud-arrow-up"></i> ${editing?'Save Changes':'Submit Product'}</button></form></section></div>`);
  qs("#productForm").onsubmit=async e=>{e.preventDefault();const btn=e.submitter;const files=[...qs("#productImages").files];if(files.length>8)return toast("Upload no more than 8 images.","warning");if(Number(qs("#productDiscount").value||0)>Number(qs("#productPrice").value))return toast("Discount price cannot be higher than regular price.","warning");const data={name:qs("#productName").value.trim(),description:qs("#productDescription").value.trim(),categoryId:qs("#productCategory").value,condition:qs("#productCondition").value,price:qs("#productPrice").value,discountPrice:qs("#productDiscount").value,stock:qs("#productStock").value,location:qs("#productLocation").value.trim(),delivery:qs("#productDelivery").value.trim(),existingImages:product?.images||[]};setButtonLoading(btn,true,"Uploading");try{const id=editing?(await updateProductRecord(product.id,data,files),product.id):await createProduct(data,files);toast(editing?"Product updated.":"Product submitted for approval.","success");setTimeout(()=>location.href=`seller-dashboard.html?product=${id}`,600);}catch(err){toast(err.message,"error","Unable to save product");}finally{setButtonLoading(btn,false);}};
}

async function renderMembership() {
  const plans=await getPlans();root().innerHTML=pageWrap(`${pageHeader("Seller Membership Plans","Upgrade, downgrade or cancel your seller membership.")}<div class="plan-grid">${plans.map(planTemplate).join("")}</div>${state.user&&state.profile?.planId?`<div class="card card-pad" style="max-width:720px;margin:30px auto 0"><h3>Current membership</h3><p>You are currently using the <strong>${escapeHtml(state.profile.planId)}</strong> plan.</p><button id="cancelMembership" class="btn btn-danger">Cancel Membership</button></div>`:''}`);
  qsa('.plan-card a').forEach(a=>{a.onclick=async e=>{e.preventDefault();if(!requireAuth())return;const plan=new URL(a.href).searchParams.get("plan");if(state.profile?.sellerStatus!=="approved"&&state.profile?.role!=="admin")return toast("Your seller account must be approved before activating a membership.","warning");try{await changeMembership(plan);toast(`Your ${plan} plan request was submitted. The plan activates after payment verification.`,"success");setTimeout(()=>location.reload(),500);}catch(err){toast(err.message,"error");}};});qs("#cancelMembership")?.addEventListener("click",async()=>{if(confirm("Cancel your membership?")){await cancelMembership();toast("Membership cancelled.","success");location.reload();}});
}
async function renderMessages() {
  if(!requireAuth())return;const conversations=await getConversations();const selected=getParam("id")||conversations[0]?.id;const messages=selected?await getMessages(selected):[];root().innerHTML=pageWrap(`${pageHeader("Messages","Communicate securely with buyers and sellers.")}<div class="message-layout card"><aside class="conversation-list">${conversations.length?conversations.map(c=>{const other=(c.participants||[]).find(x=>x!==state.user.id);const name=c.participantNames?.[other]||"DhiExpress User";return `<button class="conversation-item ${c.id===selected?'active':''}" data-conversation="${c.id}"><span class="avatar">${escapeHtml(name[0])}</span><span><strong>${escapeHtml(name)}</strong><div class="muted">${escapeHtml(c.lastMessage||'Start a conversation')}</div></span></button>`;}).join(""):emptyState("fa-comments","No conversations","Contact a seller from a product page.")}</aside><section class="message-panel">${selected?`<div class="message-header">Conversation</div><div class="message-stream" id="messageStream">${messages.length?messages.map(m=>`<div class="message-bubble ${m.senderId===state.user.id?'mine':''}">${escapeHtml(m.text)}<div style="font-size:.68rem;opacity:.7;margin-top:4px">${formatDate(m.createdAt)}</div></div>`).join(""):'<div class="muted">Send the first message.</div>'}</div><form id="messageForm" class="message-compose"><input id="messageText" required maxlength="1000" placeholder="Write a message"><button class="btn btn-primary" type="submit"><i class="fa-solid fa-paper-plane"></i></button></form>`:emptyState("fa-comments","Select a conversation","Choose a buyer or seller to view messages.")}</section></div>`);
  qsa("[data-conversation]").forEach(b=>b.onclick=()=>location.href=`messages.html?id=${b.dataset.conversation}`);qs("#messageForm")?.addEventListener("submit",async e=>{e.preventDefault();const text=qs("#messageText").value.trim();if(!text)return;await sendMessage(selected,text);qs("#messageText").value="";renderMessages();});setTimeout(()=>{const s=qs("#messageStream");if(s)s.scrollTop=s.scrollHeight;},50);
}
async function renderNotifications() {
  if(!requireAuth())return;const items=await getNotifications();root().innerHTML=pageWrap(`${pageHeader("Notifications","Order updates, account alerts and marketplace announcements.")}<div class="dashboard-layout">${dashboardNav("notifications")}<section class="dashboard-main card">${items.length?items.map(n=>`<button class="conversation-item" data-notification="${n.id}" style="width:100%"><span class="category-icon"><i class="fa-solid fa-bell"></i></span><span><strong>${escapeHtml(n.title)} ${!n.read?'<span class="badge danger">New</span>':''}</strong><div class="muted">${escapeHtml(n.message)}</div><small class="muted">${formatDate(n.createdAt)}</small></span></button>`).join(""):emptyState("fa-bell","No notifications","You are all caught up.")}</section></div>`);qsa("[data-notification]").forEach(b=>b.onclick=async()=>{await markNotificationRead(b.dataset.notification);b.querySelector(".badge")?.remove();});
}
async function renderSupport() {
  root().innerHTML=pageWrap(`${pageHeader("Help and Support","Find answers or submit a complaint to the DhiExpress team.")}<div class="grid grid-2"><section class="card card-pad"><h2>Frequently asked questions</h2>${[["How do I become a seller?","Create an account, open My Profile, submit a seller application, and wait for admin approval."],["How are orders paid?","DhiExpress supports cash on delivery, bank transfer and an optional online payment gateway."],["How do memberships work?","Approved sellers can upgrade, downgrade or cancel Bronze, Silver and Gold plans."],["How do I report a seller or order?","Use the complaint form and include the related order reference when available."]].map(([q,a])=>`<details style="padding:14px 0;border-bottom:1px solid var(--border)"><summary><strong>${q}</strong></summary><p class="muted">${a}</p></details>`).join("")}</section><section class="card card-pad"><h2>Submit a complaint</h2>${state.user?`<form id="complaintForm" class="form-grid"><div class="form-group"><label>Complaint type</label><select id="complaintType"><option>Order problem</option><option>Seller complaint</option><option>Product complaint</option><option>Payment problem</option><option>Account problem</option><option>Other</option></select></div><div class="form-group"><label>Subject</label><input id="complaintSubject" required></div><div class="form-group"><label>Order reference (optional)</label><input id="complaintOrder"></div><div class="form-group"><label>Details</label><textarea id="complaintMessage" required minlength="20"></textarea></div><button class="btn btn-primary">Submit Complaint</button></form>`:`<div class="alert info"><i class="fa-solid fa-circle-info"></i><div>Please <a class="text-primary" href="login.html?next=support.html">sign in</a> to submit a complaint.</div></div>`}<p class="muted" style="margin-top:20px">Support email: ${escapeHtml(appConfig.company.supportEmail)}</p></section></div>`);qs("#complaintForm")?.addEventListener("submit",async e=>{e.preventDefault();const btn=e.submitter;setButtonLoading(btn,true,"Submitting");try{await submitComplaint({type:qs("#complaintType").value,subject:qs("#complaintSubject").value.trim(),orderId:qs("#complaintOrder").value.trim(),message:qs("#complaintMessage").value.trim()});toast("Complaint submitted. Support will review it.","success");e.target.reset();}catch(err){toast(err.message,"error");}finally{setButtonLoading(btn,false);}});
}
function renderTerms(){root().innerHTML=pageWrap(`${pageHeader("Terms and Conditions","Effective 24 July 2026")}<article class="legal-content card card-pad"><div class="alert warning"><i class="fa-solid fa-scale-balanced"></i><div>This is a project-ready starter policy and should be reviewed by a qualified legal professional before public launch.</div></div><h2>1. Platform role</h2><p>DhiExpress provides a marketplace where businesses and individuals may list, buy and sell products or services. Unless DhiExpress is shown as the seller, the transaction is between the buyer and seller.</p><h2>2. Accounts</h2><p>Users must provide accurate information, keep account access secure, and comply with email verification and identity checks. Accounts may be suspended for fraud, abuse, prohibited listings or security risks.</p><h2>3. Product listings</h2><p>Sellers are responsible for product accuracy, legal compliance, pricing, stock, delivery promises and after-sales support. DhiExpress may review, reject or remove listings.</p><h2>4. Orders, payments and refunds</h2><p>Orders can use enabled payment methods. Payment verification, cancellation and refund eligibility depend on the order status, seller terms and applicable law.</p><h2>5. Memberships</h2><p>Seller plans may include listing limits, selling fees, featured placement and support benefits. Prices and benefits may change with notice. Users may upgrade, downgrade or cancel subject to billing rules.</p><h2>6. Prohibited activity</h2><p>Users may not list illegal goods, infringing products, dangerous items, fraudulent services, stolen goods or content that violates applicable laws or platform rules.</p><h2>7. Liability</h2><p>DhiExpress provides the platform with reasonable care but does not guarantee every seller, product, delivery or external payment service.</p><h2>8. Contact</h2><p>Questions may be sent to ${escapeHtml(appConfig.company.supportEmail)}.</p></article>`);}
function renderPrivacy(){root().innerHTML=pageWrap(`${pageHeader("Privacy Policy","How DhiExpress handles marketplace data.")}<article class="legal-content card card-pad"><div class="alert warning"><i class="fa-solid fa-shield-halved"></i><div>This starter policy should be reviewed for Maldivian law, payment partners and the final production data flow.</div></div><h2>Information collected</h2><p>DhiExpress may collect account details, profiles, seller information, products, orders, payments, messages, complaints, notifications, device and security logs.</p><h2>How information is used</h2><p>Data is used to provide authentication, marketplace transactions, customer support, fraud prevention, seller administration, analytics and legal compliance.</p><h2>Security</h2><p>Passwords are handled by Supabase Auth and are not stored in the DhiExpress database. Supabase Row Level Security and Storage policies restrict access using authenticated user IDs and admin claims.</p><h2>Sharing</h2><p>Required order details may be shared between buyers and sellers. Service providers may process hosting, authentication, storage, analytics or payments under their own terms.</p><h2>Retention and rights</h2><p>Records are retained as needed for marketplace operations, disputes, accounting and legal requirements. Users may request profile corrections or account support.</p><h2>Contact</h2><p>Privacy questions may be sent to ${escapeHtml(appConfig.company.supportEmail)}.</p></article>`);}
function renderNotFound(){root().innerHTML=pageWrap(emptyState("fa-map-signs","Page not found","The requested page does not exist.",'<a class="btn btn-primary" href="index.html">Return Home</a>'));}

async function renderAdminLogin(){if(isAdmin()){location.href="admin.html";return;}root().innerHTML=pageWrap(`<div class="form-card card">${pageHeader("Admin Login","Only the main administrator can access protected admin pages.")}<div class="alert warning" style="margin-bottom:18px"><i class="fa-solid fa-shield-halved"></i><div>Admin access is enforced with a protected administrator profile and Row Level Security. A user document role alone is not sufficient in production.</div></div><form id="adminLoginForm" class="form-grid"><div class="form-group"><label>Admin email</label><input id="adminEmail" type="email" required></div><div class="form-group"><label>Password</label><input id="adminPassword" type="password" required></div><button class="btn btn-danger" type="submit"><i class="fa-solid fa-lock"></i> Secure Admin Login</button></form></div>`);qs("#adminLoginForm").onsubmit=async e=>{e.preventDefault();const btn=e.submitter;setButtonLoading(btn,true,"Checking access");try{await signInEmail(qs("#adminEmail").value.trim(),qs("#adminPassword").value);setTimeout(()=>{if(isAdmin()||!state.configured)location.href="admin.html";else toast("This account does not have the admin claim.","error");},250);}catch(err){toast(humanAuthError(err),"error");}finally{setButtonLoading(btn,false);}};}
async function adminShell(active,contentPromise){if(!requireAdmin())return;const content=await contentPromise;root().innerHTML=pageWrap(`${pageHeader("DhiExpress Administration","Protected controls for users, sellers, products, orders, payments and website settings.")}<div class="admin-shell">${adminNav(active)}<section>${content}</section></div>`);}
async function renderAdminDashboard(){
  await adminShell("admin",(async()=>{
    const [users,products,orders,payments,complaints,errorLogs]=await Promise.all([adminList("users"),adminList("products"),adminList("orders"),adminList("payments"),adminList("complaints"),adminList("errorLogs",50)]);
    const revenue=payments.filter(payment=>["completed","paid"].includes(payment.status)).reduce((sum,payment)=>sum+Number(payment.amount||0),0);
    const openComplaints=complaints.filter(complaint=>complaint.status==="open");
    return `<div class="kpi-grid"><div class="kpi-card card"><div><span>Users</span><strong>${users.length}</strong></div><span class="kpi-icon"><i class="fa-solid fa-users"></i></span></div><div class="kpi-card card"><div><span>Products</span><strong>${products.length}</strong></div><span class="kpi-icon"><i class="fa-solid fa-box"></i></span></div><div class="kpi-card card"><div><span>Orders</span><strong>${orders.length}</strong></div><span class="kpi-icon"><i class="fa-solid fa-truck"></i></span></div><div class="kpi-card card"><div><span>Revenue</span><strong>${formatMoney(revenue)}</strong></div><span class="kpi-icon"><i class="fa-solid fa-coins"></i></span></div></div>
    <div class="content-grid"><div class="card card-pad"><h2>Platform activity</h2><div class="chart-placeholder">${[40,65,52,80,74,92,68].map((height,index)=>`<div class="chart-bar" style="height:${height}%"><span>${["Mon","Tue","Wed","Thu","Fri","Sat","Sun"][index]}</span></div>`).join("")}</div></div><div class="card card-pad"><h2>Needs attention</h2><div class="summary-line"><span>Pending products</span><strong>${products.filter(product=>product.status==="pending").length}</strong></div><div class="summary-line"><span>Pending sellers</span><strong>${users.filter(user=>user.sellerStatus==="pending").length}</strong></div><div class="summary-line"><span>Open complaints</span><strong>${openComplaints.length}</strong></div><div class="summary-line"><span>Recent client errors</span><strong>${errorLogs.length}</strong></div><button id="seedDatabase" class="btn btn-outline btn-block" style="margin-top:18px">Load Sample Categories, Plans and Products</button></div></div>
    <div class="grid grid-2" style="margin-top:22px"><div class="card card-pad"><h2>Customer complaints</h2>${openComplaints.length?`<div class="table-wrap"><table><thead><tr><th>Subject</th><th>User</th><th>Type</th><th>Action</th></tr></thead><tbody>${openComplaints.slice(0,10).map(complaint=>`<tr><td><strong>${escapeHtml(complaint.subject||"Complaint")}</strong><br><small>${escapeHtml((complaint.message||"").slice(0,90))}</small></td><td>${escapeHtml(complaint.userEmail||complaint.userId||"")}</td><td>${escapeHtml(complaint.type||"general")}</td><td><button class="btn btn-success btn-sm" data-resolve-complaint="${complaint.id}">Resolve</button></td></tr>`).join("")}</tbody></table></div>`:emptyState("fa-circle-check","No open complaints","All submitted complaints are resolved.")}</div><form id="announcementForm" class="card card-pad form-grid"><h2>Send announcement</h2><div class="form-group"><label>Title</label><input id="announcementTitle" required maxlength="100" placeholder="Marketplace update"></div><div class="form-group"><label>Message</label><textarea id="announcementMessage" required maxlength="1000" placeholder="Write the announcement for all users"></textarea></div><button class="btn btn-primary"><i class="fa-solid fa-bullhorn"></i> Send to all users</button></form></div>`;
  })());
  qs("#seedDatabase")?.addEventListener("click",async event=>{if(!confirm("Create or update sample data in Supabase?"))return;setButtonLoading(event.currentTarget,true,"Seeding");try{await seedDatabase();toast("Sample database created.","success");}catch(error){toast(error.message,"error");}finally{setButtonLoading(event.currentTarget,false);}});
  qsa("[data-resolve-complaint]").forEach(button=>button.onclick=async()=>{await adminUpdate("complaints",button.dataset.resolveComplaint,{status:"resolved",resolvedBy:state.user.id,resolvedAt:new Date().toISOString()});toast("Complaint resolved.","success");renderAdminDashboard();});
  qs("#announcementForm")?.addEventListener("submit",async event=>{event.preventDefault();const button=event.submitter;setButtonLoading(button,true,"Sending");try{await adminSendAnnouncement(qs("#announcementTitle").value.trim(),qs("#announcementMessage").value.trim());toast("Announcement sent to all users.","success");event.target.reset();}catch(error){toast(error.message,"error");}finally{setButtonLoading(button,false);}});
}
async function renderAdminUsers(){
  const users=await adminList("users");
  await adminShell("admin-users",Promise.resolve(`<div class="card card-pad"><div class="section-title"><div><h2>User Management</h2><p>Suspend, reactivate or delete marketplace accounts.</p></div></div><div class="table-wrap"><table><thead><tr><th>User</th><th>Role</th><th>Seller</th><th>Plan</th><th>Status</th><th>Actions</th></tr></thead><tbody>${users.map(user=>`<tr><td><strong>${escapeHtml(user.displayName||user.email)}</strong><br><small>${escapeHtml(user.email||"")}</small></td><td>${escapeHtml(user.role||"user")}</td><td>${escapeHtml(user.sellerStatus||"—")}</td><td>${escapeHtml(user.planId||"—")}</td><td>${statusBadge(user.status||"active")}</td><td class="table-actions">${user.id===state.user?.uid?'<span class="badge gold">Main admin</span>':`<button class="btn ${user.status==="suspended"?"btn-success":"btn-warning"} btn-sm" data-user-status="${user.id}" data-status="${user.status==="suspended"?"active":"suspended"}">${user.status==="suspended"?"Reactivate":"Suspend"}</button><button class="btn btn-danger btn-sm" data-user-delete="${user.id}">Delete</button>`}</td></tr>`).join("")}</tbody></table></div></div>`));
  qsa("[data-user-status]").forEach(button=>button.onclick=async()=>{await adminUpdate("users",button.dataset.userStatus,{status:button.dataset.status});toast("User status updated.","success");renderAdminUsers();});
  qsa("[data-user-delete]").forEach(button=>button.onclick=async()=>{if(!confirm("Delete this account from Supabase Auth and the company database?"))return;try{await adminDeleteUserAccount(button.dataset.userDelete);toast("Account deleted.","success");renderAdminUsers();}catch(error){toast(error.message,"error");}});
}
async function renderAdminSellers(){const users=(await adminList("users")).filter(u=>u.role==="seller"||(u.sellerStatus&&u.sellerStatus!=="not_applied"));await adminShell("admin-sellers",Promise.resolve(`<div class="card card-pad"><h2>Seller Management</h2><div class="table-wrap"><table><thead><tr><th>Seller</th><th>Location</th><th>Plan</th><th>Approval</th><th>Actions</th></tr></thead><tbody>${users.map(u=>`<tr><td><strong>${escapeHtml(u.businessName||u.displayName||u.email)}</strong><br><small>${escapeHtml(u.email||'')}</small></td><td>${escapeHtml(u.location||'—')}</td><td>${escapeHtml(u.planId||'None')}</td><td>${statusBadge(u.sellerStatus||'pending')}</td><td class="table-actions"><button class="btn btn-success btn-sm" data-seller-approve="${u.id}">Approve</button><button class="btn btn-danger btn-sm" data-seller-suspend="${u.id}">Suspend</button></td></tr>`).join("")}</tbody></table></div></div>`));qsa("[data-seller-approve]").forEach(b=>b.onclick=async()=>{await adminUpdate("users",b.dataset.sellerApprove,{role:"seller",sellerStatus:"approved",status:"active"});await adminUpdate("sellerProfiles",b.dataset.sellerApprove,{status:"approved"}).catch(()=>{});toast("Seller approved.","success");renderAdminSellers();});qsa("[data-seller-suspend]").forEach(b=>b.onclick=async()=>{await adminUpdate("users",b.dataset.sellerSuspend,{sellerStatus:"suspended",status:"suspended"});await adminUpdate("sellerProfiles",b.dataset.sellerSuspend,{status:"suspended"}).catch(()=>{});toast("Seller suspended.","success");renderAdminSellers();});}
async function renderAdminProducts(){
  const products=await adminList("products");
  await adminShell("admin-products",Promise.resolve(`<div class="card card-pad"><h2>Product Management</h2><div class="table-wrap"><table><thead><tr><th>Product</th><th>Seller</th><th>Price</th><th>Stock</th><th>Status</th><th>Actions</th></tr></thead><tbody>${products.map(product=>`<tr><td><div class="table-product"><img src="${escapeHtml(product.images?.[0]||"https://placehold.co/120x90?text=DX")}" alt=""><strong>${escapeHtml(product.name)}</strong></div></td><td>${escapeHtml(product.sellerName||product.sellerId)}</td><td>${formatMoney(product.discountPrice||product.price)}</td><td>${product.stock}</td><td>${statusBadge(product.status)}</td><td class="table-actions"><button class="btn btn-success btn-sm" data-product-approve="${product.id}">Approve</button><button class="btn btn-warning btn-sm" data-product-reject="${product.id}">Reject</button><a class="btn btn-ghost btn-sm" href="edit-product.html?id=${encodeURIComponent(product.id)}">Edit</a><button class="btn btn-danger btn-sm" data-product-delete="${product.id}">Delete</button></td></tr>`).join("")}</tbody></table></div></div>`));
  qsa("[data-product-approve]").forEach(button=>button.onclick=async()=>{await adminUpdate("products",button.dataset.productApprove,{status:"approved"});toast("Product approved.","success");renderAdminProducts();});
  qsa("[data-product-reject]").forEach(button=>button.onclick=async()=>{await adminUpdate("products",button.dataset.productReject,{status:"rejected"});toast("Product rejected.","warning");renderAdminProducts();});
  qsa("[data-product-delete]").forEach(button=>button.onclick=async()=>{if(confirm("Permanently delete this product?")){await adminDelete("products",button.dataset.productDelete);toast("Product deleted.","success");renderAdminProducts();}});
}
async function renderAdminOrders(){const orders=await adminList("orders");await adminShell("admin-orders",Promise.resolve(`<div class="card card-pad"><h2>Order Management</h2>${orders.length?`<div class="table-wrap"><table><thead><tr><th>Order</th><th>Buyer</th><th>Total</th><th>Payment</th><th>Status</th><th>Update</th></tr></thead><tbody>${orders.map(o=>`<tr><td>${escapeHtml(o.id)}</td><td>${escapeHtml(o.buyerName||o.buyerEmail)}</td><td>${formatMoney(o.total)}</td><td>${escapeHtml((o.paymentMethod||'').replaceAll('_',' '))}</td><td>${statusBadge(o.status)}</td><td><select data-admin-order="${o.id}">${["pending","confirmed","processing","shipped","delivered","cancelled","refunded"].map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join("")}</select></td></tr>`).join("")}</tbody></table></div>`:emptyState("fa-box","No orders","Orders will appear after customers check out.")}</div>`));qsa("[data-admin-order]").forEach(s=>s.onchange=async()=>{await adminUpdate("orders",s.dataset.adminOrder,{status:s.value});toast("Order status updated.","success");});}
async function renderAdminPayments(){const payments=await adminList("payments");await adminShell("admin-payments",Promise.resolve(`<div class="card card-pad"><h2>Payment Management</h2>${payments.length?`<div class="table-wrap"><table><thead><tr><th>Payment</th><th>Order</th><th>User</th><th>Amount</th><th>Method</th><th>Status</th><th>Actions</th></tr></thead><tbody>${payments.map(p=>`<tr><td>${escapeHtml(p.id)}</td><td>${escapeHtml(p.orderId)}</td><td>${escapeHtml(p.userId)}</td><td>${formatMoney(p.amount)}</td><td>${escapeHtml(p.method)}</td><td>${statusBadge(p.status)}</td><td><button class="btn btn-success btn-sm" data-payment-verify="${p.id}">Verify</button></td></tr>`).join("")}</tbody></table></div>`:emptyState("fa-credit-card","No payments","Payment records will appear here.")}</div>`));qsa("[data-payment-verify]").forEach(b=>b.onclick=async()=>{await adminUpdate("payments",b.dataset.paymentVerify,{status:"completed",verifiedBy:state.user.id});toast("Payment verified.","success");renderAdminPayments();});}
async function renderAdminMemberships(){
  const [plans,subscriptions]=await Promise.all([getPlans(false),adminList("subscriptions")]);
  await adminShell("admin-memberships",Promise.resolve(`<div class="grid"><div class="card card-pad"><div class="section-title"><div><h2>Membership Plans</h2><p>Edit plan pricing, benefits, limits, fees and availability.</p></div></div><div class="grid grid-3">${plans.map(plan=>`<form class="card card-pad form-grid" data-plan-form="${plan.id}"><h3>${escapeHtml(plan.name)}</h3><div class="form-group"><label>Price MVR</label><input name="price" type="number" min="0" value="${plan.price}"></div><div class="form-group"><label>Listing limit</label><input name="listingLimit" type="number" min="1" value="${plan.listingLimit}"></div><div class="form-group"><label>Selling fee %</label><input name="feePercent" type="number" min="0" max="100" step="0.1" value="${plan.feePercent}"></div><div class="form-group"><label>Benefits (one per line)</label><textarea name="benefits">${escapeHtml((plan.benefits||[]).join("\n"))}</textarea></div><label><input name="active" type="checkbox" ${plan.active!==false?"checked":""}> Active</label><button class="btn btn-primary">Save ${escapeHtml(plan.name)}</button></form>`).join("")}</div></div><div class="card card-pad"><h2>Seller Subscriptions</h2>${subscriptions.length?`<div class="table-wrap"><table><thead><tr><th>User</th><th>Plan</th><th>Price</th><th>Status</th><th>Started</th><th>Actions</th></tr></thead><tbody>${subscriptions.map(subscription=>`<tr><td>${escapeHtml(subscription.userId)}</td><td><select data-sub-plan="${subscription.id}">${plans.map(plan=>`<option value="${plan.id}" ${plan.id===subscription.planId?"selected":""}>${escapeHtml(plan.name)}</option>`).join("")}</select></td><td>${formatMoney(subscription.price)}</td><td>${statusBadge(subscription.status)}</td><td>${formatDate(subscription.startedAt)}</td><td class="table-actions"><button class="btn btn-success btn-sm" data-sub-activate="${subscription.id}">Activate / Upgrade</button><button class="btn btn-danger btn-sm" data-sub-cancel="${subscription.id}">Cancel</button></td></tr>`).join("")}</tbody></table></div>`:emptyState("fa-crown","No subscriptions","Seller membership requests will appear here.")}</div></div>`));
  qsa("[data-plan-form]").forEach(form=>form.onsubmit=async event=>{event.preventDefault();const current=plans.find(plan=>plan.id===form.dataset.planForm);await adminSavePlan({...current,id:form.dataset.planForm,price:form.price.value,listingLimit:form.listingLimit.value,feePercent:form.feePercent.value,benefits:form.benefits.value.split("\n").map(value=>value.trim()).filter(Boolean),active:form.active.checked});toast("Plan updated.","success");});
  qsa("[data-sub-activate]").forEach(button=>button.onclick=async()=>{const planId=qs(`[data-sub-plan="${button.dataset.subActivate}"]`).value;const plan=plans.find(item=>item.id===planId);await adminUpdate("subscriptions",button.dataset.subActivate,{planId,status:"active",price:Number(plan?.price||0),activatedAt:new Date().toISOString()});toast("Subscription activated.","success");renderAdminMemberships();});
  qsa("[data-sub-cancel]").forEach(button=>button.onclick=async()=>{await adminUpdate("subscriptions",button.dataset.subCancel,{status:"cancelled",cancelledAt:new Date().toISOString()});toast("Subscription cancelled.","success");renderAdminMemberships();});
}
async function renderAdminReports(){const [users,products,orders,payments]=await Promise.all([adminList("users"),adminList("products"),adminList("orders"),adminList("payments")]);const completed=payments.filter(p=>p.status==="completed").reduce((s,p)=>s+Number(p.amount||0),0);await adminShell("admin-reports",Promise.resolve(`<div class="kpi-grid"><div class="kpi-card card"><div><span>User growth</span><strong>${users.length}</strong></div><span class="kpi-icon"><i class="fa-solid fa-user-plus"></i></span></div><div class="kpi-card card"><div><span>Approved products</span><strong>${products.filter(p=>p.status==="approved").length}</strong></div><span class="kpi-icon"><i class="fa-solid fa-box"></i></span></div><div class="kpi-card card"><div><span>Delivered orders</span><strong>${orders.filter(o=>o.status==="delivered").length}</strong></div><span class="kpi-icon"><i class="fa-solid fa-truck"></i></span></div><div class="kpi-card card"><div><span>Verified payments</span><strong>${formatMoney(completed)}</strong></div><span class="kpi-icon"><i class="fa-solid fa-chart-line"></i></span></div></div><div class="card card-pad"><h2>Seven-day marketplace activity</h2><div class="chart-placeholder">${[34,58,46,77,68,88,71].map((h,i)=>`<div class="chart-bar" style="height:${h}%"><span>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]}</span></div>`).join("")}</div><p class="muted">Connect this dashboard to BigQuery or a dedicated analytics service for advanced production reporting.</p></div>`));}
async function renderAdminSettings(){
  const [settings,categories]=await Promise.all([getPublicSettings(),getCategories(false)]);
  await adminShell("admin-settings",Promise.resolve(`<div class="grid grid-2"><form id="siteSettings" class="card card-pad form-grid"><h2>Website Settings</h2><div class="form-group"><label>Site name</label><input id="siteName" value="${escapeHtml(settings.siteName||"DhiExpress")}"></div><div class="form-group"><label>Default currency</label><input id="siteCurrency" value="${escapeHtml(settings.currency||"MVR")}" disabled></div><label><input id="cashOnDelivery" type="checkbox" ${settings.cashOnDelivery!==false?"checked":""}> Enable cash on delivery</label><label><input id="bankTransfer" type="checkbox" ${settings.bankTransfer!==false?"checked":""}> Enable bank transfer</label><div class="form-group"><label>Bank name</label><input id="bankName" value="${escapeHtml(settings.bankName||"")}"></div><div class="form-group"><label>Bank account name</label><input id="bankAccountName" value="${escapeHtml(settings.bankAccountName||"")}"></div><div class="form-group"><label>Bank account number</label><input id="bankAccountNumber" value="${escapeHtml(settings.bankAccountNumber||"")}"></div><label><input id="onlinePayment" type="checkbox" ${settings.onlinePayment?"checked":""}> Enable online payment</label><label><input id="maintenanceMode" type="checkbox" ${settings.maintenanceMode?"checked":""}> Maintenance mode</label><button class="btn btn-primary">Save Settings</button></form><div class="card card-pad"><h2>Manage Categories</h2><form id="categoryForm" class="form-grid cols-2"><input id="categoryName" required placeholder="Category name"><input id="categoryIcon" value="fa-tag" placeholder="Font Awesome icon"><button class="btn btn-secondary">Add Category</button></form><div style="margin-top:18px">${categories.map(category=>`<div class="summary-line"><span><i class="fa-solid ${escapeHtml(category.icon||"fa-tag")}"></i> ${escapeHtml(category.name)} ${statusBadge(category.active===false?"suspended":"active")}</span><span class="table-actions"><button class="btn btn-ghost btn-sm" data-category-edit="${category.id}">Edit</button><button class="btn btn-danger btn-sm" data-category-delete="${category.id}">Delete</button></span></div>`).join("")}</div></div></div>`));
  qs("#siteSettings").onsubmit=async event=>{event.preventDefault();await adminSaveSettings({siteName:qs("#siteName").value.trim(),currency:"MVR",cashOnDelivery:qs("#cashOnDelivery").checked,bankTransfer:qs("#bankTransfer").checked,bankName:qs("#bankName").value.trim(),bankAccountName:qs("#bankAccountName").value.trim(),bankAccountNumber:qs("#bankAccountNumber").value.trim(),onlinePayment:qs("#onlinePayment").checked,maintenanceMode:qs("#maintenanceMode").checked});toast("Website settings saved.","success");};
  qs("#categoryForm").onsubmit=async event=>{event.preventDefault();await adminSaveCategory({name:qs("#categoryName").value.trim(),icon:qs("#categoryIcon").value.trim(),active:true,sortOrder:categories.length+1});toast("Category added.","success");renderAdminSettings();};
  qsa("[data-category-edit]").forEach(button=>button.onclick=async()=>{const current=categories.find(category=>category.id===button.dataset.categoryEdit);const name=prompt("Category name",current.name);if(!name)return;const icon=prompt("Font Awesome icon",current.icon||"fa-tag");await adminSaveCategory({...current,id:current.id,name:name.trim(),icon:(icon||"fa-tag").trim()});toast("Category updated.","success");renderAdminSettings();});
  qsa("[data-category-delete]").forEach(button=>button.onclick=async()=>{if(!confirm("Delete this category? Existing products will keep their category ID."))return;await adminDelete("categories",button.dataset.categoryDelete);toast("Category deleted.","success");renderAdminSettings();});
}
